 */
public class ProperFractionFormat_parse_TriageGen2Test {

    private ProperFractionFormat formatter;

    @Before
    public void setUp() {
        formatter = new ProperFractionFormat();
    }























    @Test
    public void testParseNumeratorOnlyNoSlash() {
        // The code says: if (c == 0) return new Fraction(num.intValue(), 1);
        // To trigger this, 'whole' must be parsed, then 'num' must be parsed, then end of string.
        // But 'whole' is parsed first. If "5" is passed, 'whole' is 5, 'num' is null.
        // If "5 6" is passed, 'whole' is 5, 'num' is 6, c is 0.
        String source = "5 6";
        ParsePosition pos = new ParsePosition(0);
        Fraction result = formatter.parse(source, pos);
        assertEquals(6, result.getNumerator());
        assertEquals(1, result.getDenominator());
    }
